```javascript
// insertWord(word, delta)
function insertWord(root, word, delta, freqMap) {
  const old = freqMap.get(word) || 0;
  const nextFreq = old + delta;
  freqMap.set(word, nextFreq);
  // propagate along path updating BSTs in nodes
  let node = root;
  for (const ch of word) {
    if (!node.next.has(ch)) node.next.set(ch, new TrieNode());
    node = node.next.get(ch);
    node.bs.insert(word, nextFreq);
